mapper.select:
select f.FileTitle as tpFileTitle, f.FileCreateUser as fileCreateUser, f.FileCreateUserName as fileCreateUserName,
flow.FlowName as tpFlowName, pro.P_Name as pName, sec.Sec_Name as secName, con.Con_Name as conName, f.T_Code as tCode,
from ${tableCodes.stp} tp left join ${tableCodes.sf} f on f.FileID=tp.tp_entityid left join SYS_Flow flow on flow.FlowID=tp.tp_flowid left join Pre_Project pro on pro.P_ID=f.FileProject left join Sec_Info sec on sec.Sec_Id=f.FileSectionID left join Con_Contract con on con.Con_Id=f.FileContract
1=1
and tp.tp_user=#{params.userId}
and tp.tp_dotime between #{params.tpStarttime} and #{params.tpEndtime}
and tp.tp_name like concat('%',#{params.tpName},'%')
and likePname(#{params.pName},pro.P_Id)=true
and pro.P_Name like concat('%',#{params.pName},'%')
and con.Con_Name like concat('%',#{params.conName},'%')
and f.FileTitle like concat('%',#{params.tpFileTitle},'%')
and tp.tp_type !=#{params.flowRecallRecord}
and tp.tp_acttype not like concat('%',#{params.approvalRecordGateway},'%')
and tp.Te_Id = #{params.teId}
and tp.tp_id in (select distinct tpu.Tpu_Tp_Id from ${tableCodes.stpu} tpu left join Sys_User u on u.U_Id=tpu.Tpu_User where u.U_Name like concat('%',#{params.tpSendName},'%') )
and (pro.P_Competent_Department in
#{code}
or ( pro.P_Id is null and tp.tp_user in
#{userId}
)
)
and tp.tp_dotime >= #{params.timeStartMin}
order by tp.${params.sortFiled} ${params.sortType}
order by tp.tp_dotime desc
limit #{params.start},#{params.size}

        select
        count( tp.tp_id)
        from ${tableCodes.stp} tp
        left join ${tableCodes.sf} f on f.FileID=tp.tp_entityid
        left join SYS_Flow flow on flow.FlowID=tp.tp_flowid
        left join Pre_Project pro on pro.P_ID=f.FileProject
        left join Sec_Info sec on sec.Sec_Id=f.FileSectionID
        left join Con_Contract con on con.Con_Id=f.FileContract

        
            1=1

            
                and tp.tp_user=#{params.userId}
            

            
                and tp.tp_dotime between #{params.tpStarttime} and #{params.tpEndtime}
            
            
                and u.U_Name like concat('%',#{params.tpSendName},'%')
            
            
                and tp.tp_name like concat('%',#{params.tpName},'%')
            
            
                and pro.P_Name like concat('%',#{params.pName},'%')
            
            
                and con.Con_Name like concat('%',#{params.conName},'%')
            
            
                and f.FileTitle like concat('%',#{params.tpFileTitle},'%')
            
            
                and tp.tp_type !=#{params.flowRecallRecord}
            
            
                and tp.tp_acttype not like concat('%',#{params.approvalRecordGateway},'%')
            
            
                and tp.Te_Id = #{params.teId}
            
            
                and   tp.tp_id in (select distinct tpu.Tpu_Tp_Id from ${tableCodes.stpu} tpu left join Sys_User u on u.U_Id=tpu.Tpu_User where       u.U_Name like concat('%',#{params.tpSendName},'%') )
            
            
                
                    and (pro.P_Competent_Department in
                    
                        #{code}
                    

                    
                        or ( pro.P_Id is null and
                        tp.tp_user in
                        
                            #{userId}
                        
                        )
                    
                    )
                
                
                    and tp.tp_dotime >= #{params.timeStartMin}

SELECT f.FileTitle AS tpFileTitle, f.FileCreateUser AS fileCreateUser, f.FileCreateUserName AS fileCreateUserName, flow.FlowName AS tpFlowName, pro.P_Name AS pName, sec.Sec_Name AS secName, con.Con_Name AS conName, f.T_Code AS tCode,
FROM sys_task_processin tp -- 使用子查询去重:按tp_entityid分组,取tp_dotime最大且tp_id最大的记录 INNER JOIN ( SELECT tp_entityid, MAX(tp_dotime) AS max_dotime FROM sys_task_processin GROUP BY tp_entityid ) tp_latest ON tp.tp_entityid = tp_latest.tp_entityid AND tp.tp_dotime = tp_latest.max_dotime LEFT JOIN sys_task_processin tp_dup ON tp.tp_entityid = tp_dup.tp_entityid AND tp.tp_dotime = tp_dup.tp_dotime AND tp.tp_id < tp_dup.tp_id INNER JOIN sys_file f ON f.FileID = tp.tp_entityid LEFT JOIN SYS_Flow flow ON flow.FlowID = tp.tp_flowid LEFT JOIN Pre_Project pro ON pro.P_ID = f.FileProject LEFT JOIN Sec_Info sec ON sec.Sec_Id = f.FileSectionID LEFT JOIN Con_Contract con ON con.Con_Id = f.FileContract tp_dup.tp_id IS NULL
AND tp.tp_user = #{params.userId}
AND tp.tp_dotime BETWEEN #{params.tpStarttime} AND #{params.tpEndtime}
AND tp.tp_name LIKE CONCAT('%', #{params.tpName}, '%')
AND likePname(#{params.pName}, pro.P_Id) = true
AND pro.P_Name LIKE CONCAT('%', #{params.pName}, '%')
AND con.Con_Name LIKE CONCAT('%', #{params.conName}, '%')
AND f.FileTitle LIKE CONCAT('%', #{params.tpFileTitle}, '%')
AND tp.tp_type != #{params.flowRecallRecord}
AND tp.tp_acttype NOT LIKE CONCAT('%', #{params.approvalRecordGateway}, '%')
AND tp.Te_Id = #{params.teId}
AND tp.tp_id IN ( SELECT DISTINCT tpu.Tpu_Tp_Id FROM ${tableCodes.stpu} tpu LEFT JOIN Sys_User u ON u.U_Id = tpu.Tpu_User WHERE u.U_Name LIKE CONCAT('%', #{params.tpSendName}, '%') )
AND ( pro.P_Competent_Department IN
#{code}
OR ( pro.P_Id IS NULL AND tp.tp_user IN
#{userId}
)
)
AND tp.tp_dotime >= #{params.timeStartMin}
ORDER BY tp.${params.sortFiled} ${params.sortType}
ORDER BY tp.tp_dotime DESC
LIMIT #{params.start}, #{params.size}

SELECT COUNT(*) FROM ( SELECT tp.tp_entityid FROM sys_task_processin tp INNER JOIN ( SELECT tp_entityid, MAX(tp_dotime) AS max_dotime FROM sys_task_processin GROUP BY tp_entityid ) tp_latest ON tp.tp_entityid = tp_latest.tp_entityid AND tp.tp_dotime = tp_latest.max_dotime LEFT JOIN sys_task_processin tp_dup ON tp.tp_entityid = tp_dup.tp_entityid AND tp.tp_dotime = tp_dup.tp_dotime AND tp.tp_id < tp_dup.tp_id INNER JOIN sys_file f ON f.FileID = tp.tp_entityid LEFT JOIN SYS_Flow flow ON flow.FlowID = tp.tp_flowid LEFT JOIN Pre_Project pro ON pro.P_ID = f.FileProject LEFT JOIN Sec_Info sec ON sec.Sec_Id = f.FileSectionID LEFT JOIN Con_Contract con ON con.Con_Id = f.FileContract
tp_dup.tp_id IS NULL
AND tp.tp_user = #{params.userId}
AND tp.tp_dotime BETWEEN #{params.tpStarttime} AND #{params.tpEndtime}
AND tp.tp_name LIKE CONCAT('%', #{params.tpName}, '%')
AND likePname(#{params.pName}, pro.P_Id) = true
AND pro.P_Name LIKE CONCAT('%', #{params.pName}, '%')
AND con.Con_Name LIKE CONCAT('%', #{params.conName}, '%')
AND f.FileTitle LIKE CONCAT('%', #{params.tpFileTitle}, '%')
AND tp.tp_type != #{params.flowRecallRecord}
AND tp.tp_acttype NOT LIKE CONCAT('%', #{params.approvalRecordGateway}, '%')
AND tp.Te_Id = #{params.teId}
AND tp.tp_id IN ( SELECT DISTINCT tpu.Tpu_Tp_Id FROM ${tableCodes.stpu} tpu LEFT JOIN Sys_User u ON u.U_Id = tpu.Tpu_User WHERE u.U_Name LIKE CONCAT('%', #{params.tpSendName}, '%') )
AND ( pro.P_Competent_Department IN
#{code}
OR ( pro.P_Id IS NULL AND tp.tp_user IN
#{userId}
)
)
AND tp.tp_dotime >= #{params.timeStartMin}
) AS distinct_count

select f.FileTitle as tpFileTitle, flow.FlowName as tpFlowName, pro.P_Name as pName, sec.Sec_Name as secName, con.Con_Name as conName, f.T_Code as tCode, ft.T_Name as tName, u1.U_Name as tpUserName,
from ${tableCodes.stp} tp
left join ${tableCodes.sf} f on f.FileID=tp.tp_entityid left join SYS_Flow flow on flow.FlowID=tp.tp_flowid left join Pre_Project pro on pro.P_ID=f.FileProject left join Sec_Info sec on sec.Sec_Id=f.FileSectionID left join Con_Contract con on con.Con_Id=f.FileContract left join ${tableCodes.stpu} tpu on tpu.Tpu_Tp_Id=tp.tp_id left join Sys_User u on u.U_Id=tpu.Tpu_User left join Sys_User u1 on u1.U_Id=tp.tp_user left join SYS_FileTemplate ft on ft.T_ID=flow.T_ID
1=1
tp.tp_user=#{params.userId}
and tp.tp_dotime between #{params.tpStarttime} and #{params.tpEndtime}
and u.U_Name like concat('%',#{params.tpSendName},'%')
and u1.U_Name like concat('%',#{params.tpDoUserName},'%')
and tp.tp_name like concat('%',#{params.tpName},'%')
and pro.P_Name like concat('%',#{params.pName},'%')
and sec.Sec_Name like concat('%',#{params.secName},'%')
and con.Con_Name like concat('%',#{params.conName},'%')
and f.FileTitle like concat('%',#{params.tpFileTitle},'%')
and tp.tp_explain like concat('%',#{params.tpExplain},'%')
and tp.ActName like concat('%',#{params.actName},'%')
and tp.tp_entityid = #{params.fileId}
and flow.FlowName like concat('%',#{params.flowName},'%')
and ft.T_Name like concat('%',#{params.tName},'%')
and tp.tp_type !=#{params.flowRecallRecord}
and >= #{params.starTime}
and<= #{params.endTime}
and tp.tp_acttype not like concat('%',#{params.approvalRecordGateway},'%')
and tp.Te_Id = #{params.teId}
order by tp.${params.sortFiled} ${params.sortType}
order by tp.tp_dotime desc
limit #{params.start},#{params.size}

select count( tp.tp_id) from ${tableCodes.stp} tp left join ${tableCodes.sf} f on f.FileID=tp.tp_entityid left join SYS_Flow flow on flow.FlowID=tp.tp_flowid left join Pre_Project pro on pro.P_ID=f.FileProject left join Sec_Info sec on sec.Sec_Id=f.FileSectionID left join Con_Contract con on con.Con_Id=f.FileContract left join ${tableCodes.stpu} tpu on tpu.Tpu_Tp_Id=tp.tp_id left join Sys_User u on u.U_Id=tpu.Tpu_User left join Sys_User u1 on u1.U_Id=tp.tp_user left join SYS_FileTemplate ft on ft.T_ID=flow.T_ID
1=1
tp.tp_user=#{params.userId}
and tp.tp_dotime between #{params.tpStarttime} and #{params.tpEndtime}
and u.U_Name like concat('%',#{params.tpSendName},'%')
and u1.U_Name like concat('%',#{params.tpDoUserName},'%')
and tp.tp_name like concat('%',#{params.tpName},'%')
and pro.P_Name like concat('%',#{params.pName},'%')
and sec.Sec_Name like concat('%',#{params.secName},'%')
and con.Con_Name like concat('%',#{params.conName},'%')
and f.FileTitle like concat('%',#{params.tpFileTitle},'%')
and tp.tp_entityid = #{params.fileId}
and tp.tp_explain like concat('%',#{params.tpExplain},'%')
and tp.ActName like concat('%',#{params.actName},'%')
and flow.FlowName like concat('%',#{params.flowName},'%')
and ft.T_Name like concat('%',#{params.tName},'%')
and tp.tp_type !=#{params.flowRecallRecord}
and >= #{params.starTime}
and<= #{params.endTime}
and tp.tp_acttype not like concat('%',#{params.approvalRecordGateway},'%')
and tp.Te_Id = #{params.teId}

select   max(tp_dotime) as maxDoTime,min(tp_dotime)as minDoTime   from  ${tableCode}  where tp_entityid=#{tpEntityid}
    
        and Te_Id = #{teId}
    
 ;

select ActID,ActName,U_Name,U_ID,TaskSendTime from SYS_Task t left join SYS_FlowActivity a on a.ActID=t.TaskCurrentActID
left join SYS_User u on u.U_ID=t.TaskUser where TaskEntityID=#{tpEntityid}

  and u.Te_Id = #{teId}
;

select uer.U_Name, uer.U_Type, uer.U_Account, sa.ActType as acttype, sa.ActHour as actHour, sc.C_Name, sc.C_ID, sf.FileProject as pId, t1.* from ${tableCode} t1 left join SYS_User uer on uer.U_ID=t1.tp_user left join SYS_File sf on sf.FileID=t1.tp_entityid left join SYS_FlowActivity sa on sa.ActID=t1.tp_actid left join SYS_Company sc on sc.C_ID=uer.C_ID where t1.tp_entityid in
#{fileId}
and user.Te_Id = #{teId}

select t2.*, pre_project.P_Name as pName, u.U_Name as createName, u1.U_Name as doUserName, sys_file.FileCreateUser as fileCreateId, sys_file.FileCreateUserName as fileCreateName, sys_file.FileFlowStatus as fileFlowStatusc from (select '已办' as taskType, tp_entityid as fileId, tp_entityid as tpEntityid, tp_id as taskId, tp_name as taskName, tp_user as doUserId, tp_dotime as doTime, tp_from as createId, tp_StartTime as createtime, tp_explain as explainStr, tp_actid as actId, tp_result as result, sf.T_Code as tCode from sys_task_processin mn left join sys_file sf on sf.FileID=mn.tp_entityid where tp_acttype='userTask'
and tp_user in
#{userId}
and tp_name like concat('%',#{params.taskname},'%')
and tp_name in
#{taskname}
UNION select '已沟通' as taskType, CP_FileID as fileId, CP_FileID as tpEntityid, CP_ID as taskId, CP_Name as taskName, CP_User as doUserId, CP_Time as doTime, CP_SendUser as createId, CP_SendTime as createtime, CP_Explain as explainStr, CP_ActID as actId, '同意' as result, sf.T_Code as tCode from sys_coordinationprocess mn left join sys_file sf on sf.FileID=mn.CP_FileID where 1=1
and CP_User in
#{userId}
and CP_Name like concat('%',#{params.taskname},'%')
and CP_Name in
#{taskname}
) t2 left join sys_file on t2.fileId = sys_file.FileID left join pre_project on sys_file.FileProject =pre_project.P_ID left join SYS_User u on u.U_ID = t2.createId left join SYS_User u1 on u1.U_ID = t2.doUserId where 1=1
order by t2.${params.sortFiled} ${params.sortType}
limit #{params.start},#{params.size}

select COUNT(1) from (select '已办' as taskType, tp_entityid as fileId, tp_entityid as tpEntityid, tp_id as taskId, tp_name as taskName, tp_user as doUserId, tp_dotime as doTime, tp_from as createId, tp_StartTime as createtime, tp_explain as explainStr, tp_actid as actId, tp_result as result from sys_task_processin where tp_acttype='userTask'
and tp_user in
#{userId}
and tp_name like concat('%',#{params.taskname},'%')
and tp_name in
#{taskname}
UNION select '已沟通' as taskType, CP_FileID as fileId, CP_FileID as tpEntityid, CP_ID as taskId, CP_Name as taskName, CP_User as doUserId, CP_Time as doTime, CP_SendUser as createId, CP_SendTime as createtime, CP_Explain as explainStr, CP_ActID as actId, '同意' as result from sys_coordinationprocess where 1=1
and CP_User in
#{userId}
and CP_Name like concat('%',#{params.taskname},'%')
and CP_Name in
#{taskname}
) t2 left join sys_file on t2.fileId = sys_file.FileID left join pre_project on sys_file.FileProject =pre_project.P_ID left join SYS_User u on u.U_ID = t2.createId left join SYS_User u1 on u1.U_ID = t2.doUserId where 1=1

select DISTINCT ${key} from (select '已办' as taskType, tp_entityid as fileId, tp_entityid as tpEntityid, tp_id as taskId, tp_name as taskName, tp_user as doUserId, tp_dotime as doTime, tp_from as createId, tp_StartTime as createtime, tp_explain as explainStr, tp_actid as actId, tp_result as result from sys_task_processin where 1=1
and tp_user in
#{userId}
and tp_name like concat('%',#{params.taskname},'%')
and tp_name in
#{taskname}
UNION select '已沟通' as taskType, CP_FileID as fileId, CP_FileID as tpEntityid, CP_ID as taskId, CP_Name as taskName, CP_User as doUserId, CP_Time as doTime, CP_SendUser as createId, CP_SendTime as createtime, CP_Explain as explainStr, CP_ActID as actId, '同意' as result from sys_coordinationprocess where 1=1
and CP_User in
#{userId}
and CP_Name like concat('%',#{params.taskname},'%')
and CP_Name in
#{taskname}
) t2 left join sys_file on t2.fileId = sys_file.FileID left join pre_project on FileProject = p_id left join SYS_User u on u.U_ID = t2.createId left join SYS_User u1 on u1.U_ID = t2.doUserId where 1=1

select stp.tp_user as Uid ,stp.tp_entityid as Fileid from Sys_Task_Processin stp
stp.tp_entityid in
#{id}
union all select sc.CC_User as Uid, sc.CC_FileID as Fileid from SYS_CarbonCopy sc
sc.CC_FileID in
